source("pre.R")
p <- function(l, e) { cat(l, ": "); r <- tr(e); if (inherits(r,"ERR")) print(r) else {dput(r)} }
m <- matrix(c(1.5,NA,3,4,5,6), 2)
p("matrix dbl", identical(arrow_to_r(arrow_array(m, schema=arrow_matrix()), to=arrow_matrix()), m))
p("matrix as list", arrow_to_r(arrow_array(m, schema=arrow_matrix())))
mi <- matrix(1:6, 3, dimnames=list(c("a","b","c"), c("x","y")))
p("matrix int dimnames", arrow_to_r(arrow_array(mi, schema=arrow_matrix()), to=arrow_matrix()))
p("matrix chr", arrow_to_r(arrow_array(matrix(c("a","bb",NA,"d"),2), schema=arrow_matrix()), to=arrow_matrix()))
p("matrix lgl", arrow_to_r(arrow_array(matrix(c(TRUE,NA,FALSE,TRUE),2), schema=arrow_matrix()), to=arrow_matrix()))
p("matrix 0 rows", arrow_to_r(arrow_array(matrix(integer(),0,3), schema=arrow_matrix()), to=arrow_matrix()))
p("matrix 0 cols", arrow_to_r(arrow_array(matrix(integer(),3,0), schema=arrow_matrix()), to=arrow_matrix()))
p("matrix 1x1", arrow_to_r(arrow_array(matrix(7L,1,1), schema=arrow_matrix()), to=arrow_matrix()))
p("matrix factor-ish", arrow_array(structure(1:4, dim=c(2L,2L), levels=c("a","b","c","d"), class="factor"), schema=arrow_matrix()))
p("matrix Date", arrow_to_r(arrow_array(structure(c(1,2,3,4), dim=c(2L,2L), class="Date"), schema=arrow_matrix()), to=arrow_matrix()))
p("matrix complex", arrow_array(matrix(1i,1,1), schema=arrow_matrix()))
p("matrix list", arrow_to_r(arrow_array(matrix(list(1,2,3,4),2), schema=arrow_matrix())))
p("3d array", arrow_array(array(1:8, c(2,2,2)), schema=arrow_matrix()))
p("vector w/ arrow_matrix", arrow_array(1:3, schema=arrow_matrix()))
p("df w/ arrow_matrix", arrow_array(data.frame(a=1), schema=arrow_matrix()))
p("matrix w/ schema +w:2 int", arrow_to_r(arrow_array(mi, schema=arrow_schema(arrow_array(mi, schema=arrow_matrix())))))
p("matrix w/ +l", arrow_to_r(arrow_array(mi, schema=arrow_schema(list(1L)))))
p("matrix w/ 'i'", arrow_to_r(arrow_array(mi, schema="i")))
p("matrix in df via stream", {d <- data.frame(a=1:3); d$m <- mi; arrow_schema(d)})
p("to matrix on list col", arrow_to_r(arrow_array(list(1:2, 3:4)), to=arrow_matrix()))
p("to matrix w/ null row", {a <- arrow_array(list(1:2, NULL, 3:4), schema=arrow_schema(arrow_array(matrix(1:2,1), schema=arrow_matrix()))); list(arrow_to_r(a), arrow_to_r(a, to=arrow_matrix()))})
p("fsl wrong len", arrow_array(list(1:2, 1:3), schema=arrow_schema(arrow_array(matrix(1:2,1), schema=arrow_matrix()))))
p("fsl all null", {a <- arrow_array(list(NULL, NULL), schema=arrow_schema(arrow_array(matrix(1:2,1), schema=arrow_matrix()))); arrow_to_r(a)})
p("fsl of chr null", {a <- arrow_array(list(c("a","b"), NULL), schema=arrow_schema(arrow_array(matrix("a",1,2), schema=arrow_matrix()))); arrow_to_r(a)})
p("fsl of df null", {s <- arrow_schema(arrow_array(list(data.frame(x=1:2,y=c("a","b"))))); a <- arrow_array(list(data.frame(x=1:2,y=c("a","b")), NULL)); arrow_to_r(a)})
p("to in df matrix", {d <- data.frame(a=1:2); s <- arrow_stream(d); 1})
# lists
p("list df w/ factor", {x <- list(data.frame(f=factor("a")), data.frame(f=factor(c("b","a")))); arrow_to_r(arrow_array(x))})
p("list df rownames", {x <- list(data.frame(a=1:2, row.names=c("r","s")), data.frame(a=3L, row.names="r")); arrow_to_r(arrow_array(x))})
p("list df 0 row first", {x <- list(data.frame(a=integer(), b=character()), data.frame(a=3L, b="z")); identical(arrow_to_r(arrow_array(x)), x)})
p("list df 0col nrows", {x <- list(data.frame(a=1:3)[,0,drop=FALSE], data.frame(a=1:2)[,0,drop=FALSE]); arrow_to_r(arrow_array(x))})
p("list df w/ list col", {d1 <- data.frame(a=1:2); d1$l <- list(1,2:3); x <- list(d1, d1[1,]); r <- arrow_to_r(arrow_array(x)); identical(r, x)})
p("list df w/ nested df", {d1 <- data.frame(a=1:2); d1$s <- data.frame(q=c("a","b")); x <- list(d1, d1[2,,drop=FALSE]); r <- arrow_to_r(arrow_array(x)); list(identical(r, x), r)})
p("list df dup names", {x <- list(data.frame(a=1, a=2, check.names=FALSE)); arrow_to_r(arrow_array(x))})
p("list df chr vs factor col", {x <- list(data.frame(a="x"), data.frame(a=factor("x"))); arrow_to_r(arrow_array(x))})
p("list df Date/POSIX", {x <- list(data.frame(d=as.Date("2020-01-01"), t=as.POSIXct(1, tz="UTC")), data.frame(d=as.Date(NA), t=as.POSIXct(2.5, tz="UTC"))); identical(arrow_to_r(arrow_array(x)), x)})
p("list posix diff tz", {x <- list(as.POSIXct(1, tz="UTC"), as.POSIXct(2, tz="Asia/Tokyo")); arrow_to_r(arrow_array(x))})
p("list posix local tz", {x <- list(as.POSIXct(1, tz="Asia/Tokyo"), as.POSIXct(2, tz="Asia/Tokyo")); arrow_to_r(arrow_array(x))})
p("list int+dbl", arrow_array(list(1L, 2.5)))
p("list int+NA", arrow_array(list(1L, NA)))
p("list chr with NA elt", arrow_to_r(arrow_array(list("a", NA_character_, character()))))
p("list of NULL/list()", arrow_to_r(arrow_array(list(list(), NULL, list(1L)))))
p("list of list(NULL)", arrow_to_r(arrow_array(list(list(NULL), list(1L, NULL)))))
p("list fn", arrow_array(list(sum)))
p("list env", arrow_array(list(globalenv())))
p("list ordered diff", arrow_array(list(factor("a", ordered=TRUE), factor("b", ordered=TRUE))))
p("list factor NA", arrow_to_r(arrow_array(list(factor(c("a",NA)), factor("b")))))
p("list raw+NULL+chr", arrow_array(list(as.raw(1), "a")))
p("list of raw() only", arrow_to_r(arrow_array(list(raw(), raw()))))
p("list of NULL then raw schema z", arrow_to_r(arrow_array(list(NULL, NULL), schema="z")))
p("list w/ attr on elems", arrow_to_r(arrow_array(list(structure(1:2, foo="x")))))
p("list of difftime", arrow_to_r(arrow_array(list(as.difftime(1, units="mins"), as.difftime(1, units="hours"))), lossy="allow"))
p("list of chr w/ arrow_type", arrow_to_r(arrow_array(list(structure("9007199254740993", arrow_type="l"), structure("5", arrow_type="l"))), lossy="character"))
p("list of mixed arrow_type", arrow_to_r(arrow_array(list(structure("9007199254740993", arrow_type="l"), structure("5", arrow_type="L"))), lossy="character"))
p("map rt", {x <- structure(list(data.frame(key=c("a","b"), value=1:2), NULL, data.frame(key=character(), value=integer())), arrow_keys_sorted=FALSE); r <- arrow_to_r(arrow_array(x)); list(identical(r,x), r)})
p("map sorted=TRUE unsorted keys", {x <- structure(list(data.frame(key=c("b","a"), value=1:2)), arrow_keys_sorted=TRUE); arrow_to_r(arrow_array(x))})
p("map NA key", {x <- structure(list(data.frame(key=c(NA,"a"), value=1:2)), arrow_keys_sorted=FALSE); arrow_to_r(arrow_array(x))})
p("map dup key", {x <- structure(list(data.frame(key=c("a","a"), value=1:2)), arrow_keys_sorted=FALSE); arrow_to_r(arrow_array(x))})
p("map factor key", {x <- structure(list(data.frame(key=factor(c("a","b")), value=1:2)), arrow_keys_sorted=FALSE); arrow_to_r(arrow_array(x))})
p("map empty", {x <- structure(list(), arrow_keys_sorted=FALSE); r <- arrow_to_r(arrow_array(x)); r})
p("map all null", {x <- structure(list(NULL), arrow_keys_sorted=FALSE); r <- arrow_to_r(arrow_array(x)); r})
p("map ipc", {x <- structure(list(data.frame(key=c("a","b"), value=1:2), NULL), arrow_keys_sorted=FALSE); d <- data.frame(i=1:2); d$m <- x; identical(arrow_read(arrow_write(d, NULL)), d)})
